  out.summaryLine = (out.hasTaskUpdate ? 'Queued callback closed (caller reached us); ' : '')
    + 'Dialing queued callback to ' + String(ba.phone || ba.callback_number || '') + '.';
  return out;
})()

(function () {
  var nowD = new Date();
