  }
  var model = String(cfg.model || '').trim();
  var nowT = new Date();
  var todayIso = nowT.getFullYear() + '-' + ('0' + (nowT.getMonth() + 1)).slice(-2) + '-' + ('0' + nowT.getDate()).slice(-2);
